solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <vector>

enum class Op { Read, Write, Close };
struct Request { Op op; std::size_t size; std::vector<std::uint8_t> data; };

class Connection
{
public:
    explicit Connection(std::uint32_t maxMessage) : maxMessage{ maxMessage } {}

    Request start()
    {
        state = State::Header;
        got.clear();
        return { Op::Read, 4, {} };
    }

    Request onRead(const std::vector<std::uint8_t>& bytes)
    {
        if (bytes.empty()) return close();
        got.insert(got.end(), bytes.begin(), bytes.end());
        if (state == State::Header)
        {
            if (got.size() < 4) return { Op::Read, 4 - got.size(), {} };
            length = got[0] | (got[1] << 8) | (got[2] << 16) | (static_cast<std::uint32_t>(got[3]) << 24);
            if (length > maxMessage) return close();
            got.clear();
            state = State::Body;
            if (length > 0) return { Op::Read, length, {} };
        }
        if (got.size() < length) return { Op::Read, length - got.size(), {} };
        std::vector<std::uint8_t> reply{ static_cast<std::uint8_t>(length), static_cast<std::uint8_t>(length >> 8),
                                          static_cast<std::uint8_t>(length >> 16), static_cast<std::uint8_t>(length >> 24) };
        reply.insert(reply.end(), got.rbegin(), got.rend());
        pendingWrite = reply;
        state = State::Writing;
        return { Op::Write, pendingWrite.size(), pendingWrite };
    }

    Request onWritten(std::size_t bytes)
    {
        if (state != State::Writing) return close();
        pendingWrite.erase(pendingWrite.begin(), pendingWrite.begin() + static_cast<std::ptrdiff_t>(std::min(bytes, pendingWrite.size())));
        if (!pendingWrite.empty()) return { Op::Write, pendingWrite.size(), pendingWrite };
        ++count;
        return start();
    }

    int served() const { return count; }

private:
    enum class State { Header, Body, Writing, Closed };
    std::uint32_t maxMessage;
    State state{ State::Header };
    std::vector<std::uint8_t> got, pendingWrite;
    std::uint32_t length{ 0 };
    int count{ 0 };

    Request close() { state = State::Closed; return { Op::Close, 0, {} }; }
};

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("one request, delivered in one piece") {
    Connection c{ 100 };
    Request r{ c.start() };
    CHECK(r.op == Op::Read); CHECK_EQ(r.size, 4u);
    r = c.onRead({ 3, 0, 0, 0 });
    CHECK(r.op == Op::Read); CHECK_EQ(r.size, 3u);
    r = c.onRead({ 'a', 'b', 'c' });
    CHECK(r.op == Op::Write);
    CHECK(r.data == (Bytes{ 3, 0, 0, 0, 'c', 'b', 'a' }));
    r = c.onWritten(7);
    CHECK(r.op == Op::Read); CHECK_EQ(r.size, 4u);
    CHECK_EQ(c.served(), 1);
}
TEST("short reads and short writes") {
    Connection c{ 100 };
    c.start();
    Request r{ c.onRead({ 2 }) };
    CHECK_EQ(r.size, 3u);
    r = c.onRead({ 0, 0, 0 });
    CHECK_EQ(r.size, 2u);
    r = c.onRead({ 'x' });
    CHECK(r.op == Op::Read); CHECK_EQ(r.size, 1u);
    r = c.onRead({ 'y' });
    CHECK(r.op == Op::Write);
    r = c.onWritten(4);
    CHECK(r.op == Op::Write);
    CHECK(r.data == (Bytes{ 'y', 'x' }));
    CHECK_EQ(c.served(), 0);
    r = c.onWritten(2);
    CHECK(r.op == Op::Read);
    CHECK_EQ(c.served(), 1);
}
TEST("empty requests, disconnects and bad lengths") {
    Connection c{ 8 };
    c.start();
    Request r{ c.onRead({ 0, 0, 0, 0 }) };
    CHECK(r.op == Op::Write);
    CHECK(r.data == (Bytes{ 0, 0, 0, 0 }));
    c.onWritten(4);
    CHECK(c.onRead({}).op == Op::Close);
    Connection d{ 8 };
    d.start();
    CHECK(d.onRead({ 9, 0, 0, 0 }).op == Op::Close);
}

